head.script:
// $p.openPopup 샘플(p_M_openPopup_*.xml) 이 띄우는 팝업 화면
scwin.onpageload = function() {
    setTimeout(scwin.showInfo, 300);
};



// 전달 데이터(dataObject.name = paramData) 와 browserPopup 창 정보 표시
scwin.showInfo = function() {
    let pd = $p.getParameter("paramData");
    let txt;
    if (pd === undefined || pd === null) {
        txt = String(pd);
    } else if (pd === "") {
        txt = "'' (빈 문자열)";
    } else if (typeof pd === "object" && pd.nodeType) {
        txt = WebSquare.xml.serialize(pd) + " (XML 문서)";
    } else if (Array.isArray(pd)) {
        txt = JSON.stringify(pd) + " (Array)";
    } else if (typeof pd === "object") {
        txt = JSON.stringify(pd) + " (JSON 객체)";
    } else {
        txt = pd + " (" + typeof pd + ")";
    }
    tbx_param.setValue("getParameter('paramData') : " + txt);

    if (window.opener) {
        tbx_browser.setValue("document.title : " + document.title
            + " / statusbar : " + window.statusbar.visible
            + " / menubar : " + window.menubar.visible
            + " / scrollbars : " + window.scrollbars.visible
            + " / toolbar : " + window.toolbar.visible);
    }
};



scwin.btn_adaptive_onclick = function() {
    tbx_adaptive.setValue("adaptive 레이아웃 적용 : " + grp_adaptive.hasClass("w2tb_adaptive_layout"));
};



// ProcessMessage 를 1초간 표시하고 표시 영역(차단 레이어 위치·크기)을 출력
scwin.btn_processMsg_onclick = function() {
    $p.showProcessMessage("처리 중입니다.");
    setTimeout(function() {
        let list = document.querySelectorAll(".w2_proc_modal, [id^='___processbar'].w2modal");
        let ret = "";
        for (let i = 0; i < list.length; i++) {
            let r = list[i].getBoundingClientRect();
            if (r.width > 0 && r.height > 0) {
                ret = "ProcessMessage 차단 영역 : left " + Math.round(r.left) + ", top " + Math.round(r.top) + ", " + Math.round(r.width) + " x " + Math.round(r.height);
                break;
            }
        }
        $p.hideProcessMessage();
        tbx_processMsg.setValue(ret || "ProcessMessage 차단 영역 : 없음");
    }, 1000);
};



scwin.btn_close_onclick = function() {
    $p.closePopup();
};
